mapper.sql:
WHERE 1=1

    AND a.person_name LIKE CONCAT('%', #{personName}, '%')


    AND a.month = #{month}


    AND a.classes = #{classes}


    AND a.id_card = #{idCard}



    AND (o.office_name LIKE CONCAT('%', #{organization}, '%') OR backup_o.office_name LIKE CONCAT('%', #{organization}, '%'))


    AND (p.position_name LIKE CONCAT('%', #{workshop}, '%') OR backup_p.position_name LIKE CONCAT('%', #{workshop}, '%'))


    AND (fpl.prod_line_name LIKE CONCAT('%', #{process}, '%') OR backup_fpl.prod_line_name LIKE CONCAT('%', #{process}, '%'))


    AND (wg.work_group_name LIKE CONCAT('%', #{workGroupName}, '%') OR backup_wg.work_group_name LIKE CONCAT('%', #{workGroupName}, '%'))

mapper.select:
SELECT a.id, a.person_name AS "personName", a.month, a.classes, a.id_card AS "idCard", a.employee_id AS "employeeId", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks, a.status FROM swm_person_schedule a WHERE a.id_card = #{idCard}
AND a.month = #{month}
AND a.status = '0' AND (1=1 OR a.tenant_id IS NOT NULL) ORDER BY a.update_date DESC

SELECT DISTINCT sp.identity_card AS "key", COALESCE(wg.work_group_name, backup_wg.work_group_name) AS "value" FROM swm_person sp -- 閸忓疇浠堥張鈧弬鎵畱 fms_worker 鐠佹澘缍嶉敍鍫滃▏閻?EXISTS 娴兼ê瀵查幀褑鍏橀敍? LEFT JOIN fms_worker w ON sp.identity_card = w.identity_code COLLATE utf8mb4_general_ci AND NOT EXISTS ( SELECT 1 FROM fms_worker fw2 WHERE fw2.identity_code = w.identity_code AND fw2.create_date > w.create_date ) LEFT JOIN fms_work_group wg ON w.work_group_id = wg.id -- 婢跺洨鏁ら崗瀹犱粓閿涘牓鈧俺绻僺wm_person鐞涖劋鑵戞穱婵嗙摠閻ㄥ墖eam鐎涙顔岄崗瀹犱粓閿? LEFT JOIN fms_work_group backup_wg ON sp.team = backup_wg.id COLLATE utf8mb4_general_ci WHERE sp.identity_card IN
#{idCard}
AND sp.status = '0'

SELECT a.id AS "id", a.person_name AS "personName", a.month AS "month", a.id_card AS "idCard" FROM swm_person_schedule a
a.status = '0'
AND a.month = #{month}
AND a.tenant_id = #{tenantId}
AND #{random} = #{random}
ORDER BY a.id

SELECT a.id_card FROM swm_person_schedule a


        AND a.id IN

            #{id}

SELECT a.id, sp.name as personName, a.id_card, sp.id as employeeId, sp.safety_helmet_id as deviceId, sp.person_type, a.classes FROM `swm_person_schedule` a LEFT JOIN swm_person sp on a.id_card = sp.identity_card
a.status = '0' and sp.status = '0'
AND a.tenant_id = #{tenantId}
